package cn.dreamingfish.launcher.downloads;
import java.util.*;
public record TaskRequest(TaskKind kind,Map<String,String> inputs) {
 public TaskRequest {Objects.requireNonNull(kind);inputs=Map.copyOf(inputs);Set<String> keys=switch(kind){case VANILLA_INSTALL->Set.of("instanceId","versionId","metadataSha1");case FABRIC_INSTALL->Set.of("instanceId","versionId","metadataSha1","fabricVersion","profileSha256","planSha256");case LOADER_INSTALL->Set.of("instanceId","versionId","metadataSha1","loader","loaderVersion","sourceSha256","planSha256");case INSTALLATION_VERIFY->Set.of("instanceId");case MOD_VERIFY->Set.of("entryId");case MOD_REMOVE->Set.of("instanceId","planSha256");case MOD_INSTALL->Set.of("instanceId","source","projectId","versionId","fileKey","gameVersion","loader","planSha256");case MOD_DOWNLOAD->Set.of("source","projectId","versionId","fileKey","gameVersion","loader","digestAlgorithm","digest","size");};if(!inputs.keySet().equals(keys))throw new IllegalArgumentException("任务输入字段无效");
  inputs.forEach((k,v)->{if(v==null||v.isBlank()||v.length()>256||v.chars().anyMatch(Character::isISOControl)||v.contains(":")||v.contains("/")||v.contains("\\"))throw new IllegalArgumentException("任务输入不接受路径、URL 或凭据");if(k.endsWith("Id")&&(k.equals("instanceId")||k.equals("entryId")))uuid(v);if(k.equals("metadataSha1")&&!v.matches("[0-9a-f]{40}"))throw new IllegalArgumentException("元数据摘要无效");});
  if(kind==TaskKind.FABRIC_INSTALL&&(!inputs.get("fabricVersion").matches("[A-Za-z0-9][A-Za-z0-9_.+\\-]{0,127}")||!inputs.get("profileSha256").matches("[0-9a-f]{64}")||!inputs.get("planSha256").matches("[0-9a-f]{64}")))throw new IllegalArgumentException("Fabric固定任务字段无效");
  if(kind==TaskKind.LOADER_INSTALL){new cn.dreamingfish.launcher.loaders.LoaderIdentity(cn.dreamingfish.launcher.GameInstance.LoaderKind.valueOf(inputs.get("loader")),inputs.get("loaderVersion"));if(!inputs.get("sourceSha256").matches("[0-9a-f]{64}")||!inputs.get("planSha256").matches("[0-9a-f]{64}"))throw new IllegalArgumentException("核心固定任务摘要无效");}
  if((kind==TaskKind.MOD_INSTALL||kind==TaskKind.MOD_REMOVE)&&!inputs.get("planSha256").matches("[0-9a-f]{64}"))throw new IllegalArgumentException("模组实例计划摘要无效");
  if(kind==TaskKind.MOD_INSTALL)new cn.dreamingfish.launcher.mods.ModFileRef(cn.dreamingfish.launcher.mods.ModSource.valueOf(inputs.get("source")),inputs.get("projectId"),inputs.get("versionId"),inputs.get("fileKey"));
  if(kind==TaskKind.MOD_DOWNLOAD){if(!Set.of("MODRINTH","CURSEFORGE").contains(inputs.get("source"))||!inputs.get("projectId").matches("[A-Za-z0-9_-]{1,128}")||!inputs.get("versionId").matches("[A-Za-z0-9_-]{1,128}")||!inputs.get("fileKey").matches("[0-9a-f]{64}")||!inputs.get("loader").matches("[a-z0-9_-]{1,32}")||inputs.get("gameVersion").length()>128)throw new IllegalArgumentException("模组任务引用或兼容条件无效");new FileDigest(FileDigest.Algorithm.valueOf(inputs.get("digestAlgorithm")),inputs.get("digest"));String size=inputs.get("size");if(!size.matches("0|[1-9][0-9]{0,10}")||Long.parseLong(size)>2L*1024*1024*1024)throw new IllegalArgumentException("模组任务长度无效");}
 }
 public static UUID uuid(String text){try{var id=UUID.fromString(text);if(!id.toString().equals(text))throw new IllegalArgumentException();return id;}catch(RuntimeException invalid){throw new IllegalArgumentException("需要规范 UUID");}}
}
